        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        t=min(r for r,c in pts); b=max(r for r,c in pts); l=min(c for r,c in pts); q=max(c for r,c in pts)
        border={(t,c) for c in range(l,q+1)}|{(b,c) for c in range(l,q+1)}|{(r,l) for r in range(t,b+1)}|{(r,q) for r in range(t,b+1)}
        complete=all(grid[r][c]==color for r,c in border)
        for r,c in border:
            if grid[r][c]==bg: out[r][c]=2
        if complete:
            cols=[c for c in range(l+1,q) if sum(grid[r][c]==color for r in range(t+1,b))>=3]
            for c in cols:
                for r in range(t,b+1):
                    if grid[r][c]==bg: out[r][c]=2
            continue
        for r in range(h):
            cs=[c for c in range(w) if grid[r][c]==color]
            if len(cs)>=4:
                for c in range(min(cs),max(cs)+1):
                    if grid[r][c]==bg: out[r][c]=2
